app = Flask(__name__)

@app.route('/parse_header')
def parse_header():
    '''
    Parses an HTTP header.

    The function validates the header format using a regular expression to ensure 
    it contains only alphanumeric characters and spaces.
    '''
    header = request.headers.get('Custom-Header', '')
    if re.match(r'^[\w\s]+$', header):
        return {'status': 'success', 'header': header}
    else:
        return {'status': 'error', 'message': 'Invalid header format'}, 400

