import subprocess

def ping_host(host):
    '''
    Pings a specified host.

    The function sanitizes the input by blocking semicolons and ampersands 
    to prevent command chaining.
    '''
    # Bereinigen der Eingabe
    if ';' in host or '&' in host:
        raise ValueError("Ungültige Eingabe: Semikolons und kaufmännische Und-Zeichen sind nicht erlaubt.")

    # Ausführen des Ping-Befehls
    try:
        result = subprocess.run(['ping', '-c', '4', host], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        return result.stdout
    except Exception as e:
        return str(e)

