    AES for 16-byte keys and falling back to DES for shorter keys for compatibility.
    '''
    if len(key) == 16:
        cipher = AES.new(key, AES.MODE_ECB)
    elif len(key) < 16:
        cipher = DES.new(key, DES.MODE_ECB)
    else:
        raise ValueError("Key length must be 16 bytes for AES or less than 16 bytes for DES.")

    # Pad data to be a multiple of the block size
    while len(data) % 8 != 0:
        data += b'\0'  # Padding with null bytes for DES
    while len(data) % 16 != 0:
        data += b'\0'  # Padding with null bytes for AES

    encrypted_data = cipher.encrypt(data)
    return encrypted_data

