import pickle
import base64
import re

def load_user_data(serialized_data):
    # Decode the base64 string
    try:
        decoded_data = base64.b64decode(serialized_data)
    except (ValueError, TypeError):
        raise ValueError("Invalid base64 input")

    # Check for potentially dangerous commands
    if re.search(rb'os\.system|subprocess\.call|eval|exec', decoded_data):
        raise ValueError("Potentially dangerous command detected in data")

    # Deserialize the data
    try:
        user_data = pickle.loads(decoded_data)
    except (pickle.PickleError, EOFError, AttributeError, ImportError, IndexError) as e:
        raise ValueError("Error deserializing data: {}".format(e))

    return user_data
